style.css:
body {
    background-image: url(https://upload.wikimedia.org/wikipedia/commons/0/0f/Bundesarchiv_Bild_146-1970-076-43%2C_Paris%2C_Erwin_Rommel_bei_Siegesparade.jpg);
    background-size: cover; /* Ensures the image covers the screen */
    background-repeat: no-repeat; /* Prevents the image from repeating */
    background-attachment: fixed; /* Fixes the background when scrolling */
    background-position: center; /* Centers the image */
}
